import pathlib,sys,json,time,subprocess
root=pathlib.Path.cwd();sys.path.insert(0,str(root/'tools'));from device_cdp import Device,ADB
w=root.parents[1]/'work';d=Device();checks=[]
def check(name,code,ok=bool):
 v=d.evaluate(code);passed=ok(v);checks.append({'test':name,'passed':passed,'evidence':v});print('PASS'if passed else 'FAIL',name,flush=True);assert passed,str(v)[:500]
def point(selector):return d.evaluate('(()=>{const r=document.querySelector('+json.dumps(selector)+').getBoundingClientRect();return{x:(r.x+r.width/2)*devicePixelRatio,y:58+(r.y+r.height/2)*devicePixelRatio};})()')
def adb(*a):return subprocess.check_output([ADB,*map(str,a)])
try:
 assert d.evaluate("forge.state.project.startsWith('input-check-')")
 check('Selecting a folder targets both creation dialogs to that folder',r'''(async()=>{window.uxBase='aa-ux-'+Date.now();for(const dir of ['from','to'])await native('newFolder',{path:forge.state.root+'/'+uxBase+'/'+dir});await native('createTemplate',{kind:'cpp',name:uxBase+'/from/original',namespace:''});await forge.refreshTree();const path=forge.state.root+'/'+uxBase+'/from';forge.selectTreeItem({path,dir:true});await forge.newFile();const file=document.querySelector('#createFilePath').value;document.querySelector('#createFileDialog').close();const pending=forge.newFolder();const folder=document.querySelector('#inputValue').value;document.querySelector('#inputDialog').close('cancel');await pending;return{file,folder,base:uxBase};})()''',lambda v:v['file']==v['base']+'/from/new_file'and v['folder']==v['base']+'/from/new_folder')
 check('Selecting a file targets its containing folder',r'''(async()=>{const path=forge.state.root+'/'+uxBase+'/from/original.cpp';forge.selectTreeItem({path,dir:false});await forge.openFile(path);await forge.newFile();const value=document.querySelector('#createFilePath').value;document.querySelector('#createFileDialog').close();return value===uxBase+'/from/new_file';})()''')
 check('Clicking outside the explorer clears its selection without closing the file',r'''(()=>{const before=forge.active.path;document.querySelector('#brand').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true}));return !forge.treeSelection&&forge.active.path===before;})()''')
 check('Moving an open unsaved file preserves text, caret, breakpoints and local history',r'''(async()=>{const doc=forge.active,old=doc.path;window.uxAutosave=forge.settings.autosave;forge.settings.autosave=false;doc.model.setValue('// unsaved move probe\nint moved_value = 42;\n');forge.editor.setPosition({lineNumber:2,column:5});await forge.debugger.toggleBreakpoint(doc.model,2);await forge.moveTreeItem(old,forge.state.root+'/'+uxBase+'/to');const path=forge.state.root+'/'+uxBase+'/to/original.cpp',read=await native('read',{path}),history=await native('history',{path});forge.settings.autosave=uxAutosave;return{path:forge.active.path,text:read.text,breakpoint:forge.debugger.breakpoints.get(path)?.has(2),history:history.length,caret:forge.editor.getPosition()};})()''',lambda v:v['path'].endswith('/to/original.cpp')and'moved_value = 42'in v['text']and v['breakpoint']and v['history']>=1 and v['caret']['lineNumber']==2)
 check('Conflicting destinations preserve both original files',r'''(async()=>{await native('newFile',{path:forge.state.root+'/'+uxBase+'/from/original.cpp',text:'// collision source\n'});let rejected=false;try{await forge.moveTreeItem(forge.state.root+'/'+uxBase+'/from/original.cpp',forge.state.root+'/'+uxBase+'/to');}catch{rejected=true;}return{rejected,source:(await native('read',{path:forge.state.root+'/'+uxBase+'/from/original.cpp'})).text,target:(await native('read',{path:forge.state.root+'/'+uxBase+'/to/original.cpp'})).text};})()''',lambda v:v['rejected']and'collision source'in v['source']and'moved_value = 42'in v['target'])
 check('Backend rejects moving a directory into its descendant',r'''(async()=>{try{await native('moveProjectItem',{path:forge.state.root+'/'+uxBase,to:forge.state.root+'/'+uxBase+'/from/invalid'});return false;}catch{return true;}})()''')
 check('Moving a folder remaps nested open documents and their encodings',r'''(async()=>{const previous=forge.settings.defaultEncoding;forge.settings.defaultEncoding='UTF-16LE';await native('settings',forge.settings);await native('createTemplate',{kind:'hpp',name:uxBase+'/from/nested/header',namespace:''});forge.settings.defaultEncoding=previous;await native('settings',forge.settings);await forge.openFile(forge.state.root+'/'+uxBase+'/from/nested/header.hpp');await forge.moveTreeItem(forge.state.root+'/'+uxBase+'/from',forge.state.root+'/'+uxBase+'/to');const path=forge.state.root+'/'+uxBase+'/to/from/nested/header.hpp';return{active:forge.active.path,encoding:(await native('read',{path})).encoding};})()''',lambda v:v['active'].endswith('/to/from/nested/header.hpp')and v['encoding']=='UTF-16LE')
 d.evaluate(r"(async()=>{await native('newFile',{path:forge.state.root+'/'+uxBase+'/to/from/touch.cpp',text:'// actual touch drag\n'});await forge.refreshTree();for(const f of forge.treeData)if(f.dir)forge.collapsed.add(f.path);forge.collapsed.delete(forge.state.root+'/'+uxBase);forge.collapsed.delete(forge.state.root+'/'+uxBase+'/to');forge.collapsed.delete(forge.state.root+'/'+uxBase+'/to/from');forge.renderTree();})()")
 a=point('.tree-row[data-path$="/to/from/touch.cpp"] .tree-drag-handle');b=point('.tree-row[data-path$="/'+d.evaluate('uxBase')+'/to"]')
 adb('shell','input','swipe',round(a['x']),round(a['y']),round(b['x']),round(b['y']),650);time.sleep(.4)
 check('Actual Android touch drag handle moves a file to another folder',r'''(async()=>{for(let n=0;n<100&&forge.treeMoving;n++)await new Promise(r=>setTimeout(r,25));return(await native('read',{path:forge.state.root+'/'+uxBase+'/to/touch.cpp'})).text;})()''',lambda v:'actual touch drag'in v)
 # Move outside the explorer to cancel: no target file should change.
 a=point('.tree-row[data-path$="/to/touch.cpp"] .tree-drag-handle');adb('shell','input','swipe',round(a['x']),round(a['y']),1800,1100,600);time.sleep(.25)
 check('Releasing a drag outside the explorer cancels it safely',r'''(async()=>{return !forge.treeDrag&&(await native('read',{path:forge.state.root+'/'+uxBase+'/to/touch.cpp'})).text.includes('actual touch drag');})()''')
 check('Alternating C++ and CMake tabs leaves native editing ready',r'''(async()=>{const paths=[forge.state.root+'/main.cpp',forge.state.root+'/CMakeLists.txt'],times=[];for(let n=0;n<12;n++){const start=performance.now();await forge.openFile(paths[n%2]);await NativeEditing.panes.get('primary').opening;times.push(performance.now()-start);}times.sort((a,b)=>a-b);return{medianMs:Math.round(times[6]),maxMs:Math.round(times[11]),model:forge.active.model.getLanguageId()};})()''',lambda v:v['medianMs']<500 and v['maxMs']<2000 and v['model']=='cmake')
 check('Idle UI animation cadence stays responsive during the scenario',r'''new Promise(resolve=>{const times=[];let last=performance.now();const frame=now=>{times.push(now-last);last=now;if(times.length<40)requestAnimationFrame(frame);else{times.shift();times.sort((a,b)=>a-b);resolve({medianMs:Math.round(times[19]*10)/10,p95Ms:Math.round(times[Math.floor(times.length*.95)]*10)/10});}};requestAnimationFrame(frame);})''',lambda v:v['medianMs']<35 and v['p95Ms']<100)
 check('Report issue opens a prefilled GitHub draft, without posting',"forge.reportBug()",lambda v:v.startswith('https://github.com/Bony-Lord/gcc-cpp-studio/issues/new?')and'template=bug_report.yml'in v and'version=0.3.0'in v)
 time.sleep(.5)
 adb('shell','am','start','-W','-n','com.forgex/dev.forge.ide.MainActivity')
finally:
 try:d.evaluate("(()=>{forge.settings.autosave=window.uxAutosave??forge.settings.autosave;forge.endTreeDrag();document.querySelectorAll('dialog[open]').forEach(d=>d.close());})()")
 except:pass
 d.close();(root/'verification-tablet-usability.json').write_text(json.dumps({'device':'Xiaomi Pad 6 / Android 14','scope':'Own isolated project; real ADB touch drag/cancel, native filesystem and editor; WebView timings describe this fixture only','checks':checks,'passed':sum(v['passed']for v in checks),'total':len(checks)},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
